entries[364381] = { ["name"] = "Stellarer Verfall", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer instabile Kern bricht kontinuierlich aus und fügt Spielercharakteren innerhalb von 5 Metern alle 1 Sek. 3133 Schattenschaden zu. Zusätzlich wird der Schaden, den sie durch den instabilen Kern erleiden, 6 Sek. lang um 100% erhöht. Dieser Effekt ist stapelbar. Jeglicher Schaden, der Spielercharakteren auf diese Weise zugefügt wird, wird auch dem Kern zugefügt." }
