entries[364686] = { ["name"] = "Erneuernde Blüte", ["text"] = "100 Meter Reichweite\nSofort\nHeilung durch 'Verjüngung' hat eine Chance von 25%, 'Erneuernde Blüte' zu gewähren, was um (20.8% der Zaubermacht) Gesundheit im Verlauf von 8 Sek. heilt. 'Rasche Heilung' kann 'Erneuernde Blüte' verbrauchen." }
entries[364687] = { ["name"] = "Aggressiver Puttrid", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (200), Schimmer der Arglist , Puttridengitter" }
entries[364688] = { ["name"] = "Stabilisierter Geomentar", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (400), Schimmer der Metamorphose , Geomentargitter" }
entries[364689] = { ["name"] = "Omnipotenzialkern", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (350), Schimmer der Animation , Ungeformtes Gitter" }
entries[364690] = { ["name"] = "Resonantes Echo", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (250), Schimmer des Überlebens , Ungeformtes Gitter" }
entries[364691] = { ["name"] = "Protoprickler", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (450), Schimmer der Entdeckung , Aurelidengitter" }
entries[364692] = { ["name"] = "Flinker Schattenfall", ["text"] = "Animabonus\nSofort\nVerringert die Abklingzeit von 'Schattenwort: Tod' um 5 Sek." }
entries[364694] = { ["name"] = "Erdkugel", ["text"] = "15 Meter Reichweite\nSofort\nExplodiert beim Einschlag. Fügt dem Gegner Schaden zu und betäubt ihn für 2 Sek." }
entries[364695] = { ["name"] = "Schreckensmeduse", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (400), Schimmer des Räubertums , Aurelidengitter" }
entries[364696] = { ["name"] = "Pflanzliches Heilmittel werfen", ["text"] = "100 Meter Reichweite\nSofort\nSchleudert Feroz' pflanzliches Heilmittel. Vom Effekt getroffene Peitscher in den Katalysatorgärten werden entweder wieder zahm oder sie erleiden 8 Schaden und werden aufgebracht." }
entries[364697] = { ["name"] = "Mikrolicid", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (150), Schimmer der Befriedigung , Helicidgitter" }
entries[364698] = { ["name"] = "Schnecki", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (400), Schimmer des Gleichmuts , Helicidgitter" }
entries[364699] = { ["name"] = "Plageviperid", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (150), Schimmer der Wachsamkeit , Viperidengitter" }
entries[364700] = { ["name"] = "Wühlender Vombata", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (350), Schimmer der Gerissenheit , Vombatagitter" }
entries[364701] = { ["name"] = "Ewige Strahlung", ["text"] = "Unbegrenzte Reichweite\nSofort\nSpielercharaktere in der Singularität erleiden alle 2 Sek. 2086 kosmischen Schaden. Dieser Effekt ist stapelbar." }
entries[364703] = { ["name"] = "Hoppelnder Leporid", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGenesispartikel (250), Schimmer der Erneuerung , Leporidengitter" }
entries[364712] = { ["name"] = "Ping" }
entries[364715] = { ["name"] = "Jahreszeiten der Fülle", ["text"] = "Der Einsatz von 'Segen des Sommers' gewährt nach 10 Sek. 'Äquinoktium'.\n\nÄquinoktium: Erhöht die Effektivität von 'Segen des Sommers' 10 Sek. lang um 100%." }
entries[364719] = { ["name"] = "Pflichtgebundener Hammer", ["text"] = "Vergeltung\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Urteil des Templers' löst automatisch 'Göttlicher Sturm' aus.\n\nHeilig\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Licht der Morgendämmerung' aus.\n\nSchutz\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Schild der Rechtschaffenen' aus." }
entries[364722] = { ["name"] = "Strahlende Glut", ["text"] = "Erhöht die Dauer von 'Ascheweihung' um 50%. Wenn Ihr den Effekt vorzeitig aufhebt, wird die Abklingzeit abhängig von der verbleibenden Dauer um bis zu 50% verringert." }
entries[364724] = { ["name"] = "Göttliche Resonanz", ["text"] = "30 Meter Reichweite\nHeilig\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. 'Heiliger Schock' ein. Dieser Effekt hält 15 Sek. lang an.\n\nVergeltung\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. 'Richturteil' ein. Dieser Effekt hält 15 Sek. lang an.\n\nSchutz\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. 'Schild des Rächers' ein. Dieser Effekt hält 15 Sek. lang an." }
entries[364731] = { ["name"] = "Ruf der Herrschaft" }
entries[364732] = { ["name"] = "Bauplanreintegration: Wilder Skarabid", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für den wilden Skarabiden und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen." }
entries[364733] = { ["name"] = "Tobender Vortex der Vesperglocke", ["text"] = "Wenn 3 Aufladungen des Vespertotems verbraucht sind, strahlt das Vespertotem (300% der Zaubermacht) Arkanschaden und (110% der Zaubermacht) Heilung innerhalb von 15 Metern aus." }
entries[364734] = { ["name"] = "Elementarverbunden", ["text"] = "Auf bis zu 5 verbündete Ziele, die mit 'Kettenernte' geheilt wurden, wird 'Springflut' gewirkt. Auf bis zu 5 gegnerische Ziele, denen mit 'Kettenernte' Schaden zugefügt wurde, wird 'Flammenschock' gewirkt. Kritische Treffer mit 'Flammenschock' verringern die Abklingzeit von 'Kettenernte' um 1.0 Sek." }
entries[364735] = { ["name"] = "Samen des ungezügelten Wachsens", ["text"] = "Jeder Impuls des Schadenseffekts von 'Faetransfusion' verringert die Abklingzeit von 'Wildgeist' um 9.0 Sek. und erhöht Eure kritische Trefferchance für 15 Sek. um 4%." }
entries[364736] = { ["name"] = "Zersplitterte Elemente", ["text"] = "Jeder zusätzliche Einsatz von 'Blitzschlag' , der von 'Urzeitliche Welle' erzeugt wird, erhöht Euer Tempo 12 Sek. lang um 10%." }
entries[364737] = { ["name"] = "Pflanzlich induzierte Raserei" }
entries[364738] = { ["name"] = "Einigkeit", ["text"] = "Runenschnitzmacht\nGewährt einen legendären Effekt Eures auserwählten Pakts.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Schamane" }
entries[364739] = { ["name"] = "Pakt der Seelenpirscher", ["text"] = "Wenn Euer 'Resonierender Pfeil' einem Ziel Schaden zufügt, wird die kritische Trefferchance Eurer Gruppe für 10 Sek. um 10% erhöht." }
entries[364740] = { ["name"] = "Beutel mit Klingenbruchstücken", ["text"] = "Durch 'Schinderschuss' ausgelöste Bonuseinsätze von 'Tödlicher Schuss' lassen 6 Ziele innerhalb von 12 Metern bluten, was ihnen 60% des von 'Tödlicher Schuss' verursachten Schadens im Verlauf von 6 Sek. zufügt." }
entries[364741] = { ["name"] = "Tasche mit Munition", ["text"] = "Bis zu 2 der von Eurem 'Todeschakram' getroffenen Ziele werden zusätzlich von 'Explosivschuss' getroffen." }
entries[364742] = { ["name"] = "Fragmente des Ältestengeweihs", ["text"] = "Wenn 'Wilde Geister' weniger als 5 Ziele trifft, besteht eine Chance von 100%, dass der Schaden von 'Wilde Geister' erneut verursacht wird." }
entries[364743] = { ["name"] = "Einigkeit", ["text"] = "Runenschnitzmacht\nGewährt einen legendären Effekt Eures auserwählten Pakts.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Jäger" }
entries[364744] = { ["name"] = "Bauplanreintegration: Multihuhn", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für das Multihuhn und ermöglicht es Euch, es mittels Protoformsynthese herzustellen." }
entries[364745] = { ["name"] = "Bauplanreintegration: Aggressiver Puttrid", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für den aggressiven Puttriden und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen." }
entries[364746] = { ["name"] = "Bauplanreintegration: Stabilisierter Geomentar", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für den stabilisierten Geomentar und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen." }
entries[364747] = { ["name"] = "Bauplanreintegration: Omnipotenzialkern", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für den Omnipotenzialkern und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen." }
entries[364748] = { ["name"] = "Endgültiges Urteil", ["text"] = "Wenn ein Gegner mit 'Fesseln der Unwürdigen' belegt wird, erhaltet Ihr sofort eine Rune und Euer Schaden wird um 4% erhöht. Hält 15 Sek. lang an und ist bis zu 20% stapelbar." }
entries[364749] = { ["name"] = "Bauplanreintegration: Resonantes Echo", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für das resonante Echo und ermöglicht es Euch, es mittels Protoformsynthese herzustellen." }
entries[364750] = { ["name"] = "Schreckenspirscher rufen", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört für 12 Sek. 2 wilde Schreckenspirscher, die das Ziel angreifen." }
entries[364751] = { ["name"] = "Schreckenspirscher rufen", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört einen dämonischen Meteor voller Wildwichtel herab, die hervorbrechen, um das Ziel anzugreifen.\n\nFügt beim Einschlag allen Gegnern innerhalb von 8 Metern um das Ziel bis zu [3 * (55.6876% der Zaubermacht)] Schattenflammenschaden zu [ Hand der Verdammnis : belegt alle getroffenen Ziele mit 'Verdammnis' ] und beschwört, basierend auf den aufgezehrten Seelensplittern, bis zu 3 Wildwichtel." }
entries[364752] = { ["name"] = "Unstillbarer Hunger", ["text"] = "Wenn 'Schwärmender Nebel' endet, fügt die Fähigkeit 5 Gegnern in der Nähe (86.42% der Angriffskraft) Schattenschaden zu und heilt Euch um 25% des verursachten Schadens. Der Schaden erhöht sich pro 1 Runenmacht, die Ihr verbraucht habt, während 'Schwärmender Nebel' aktiv war, um 2%." }
entries[364753] = { ["name"] = "Bauplanreintegration: Protoprickler", ["text"] = "Sofort\nGewährt der Protoformschmiede den Bauplan für den Protoprickler und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen." }
